// Asset-only source pattern recovery for BLU-02. No original game scripts execute.
using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Security.Cryptography;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
public static class GoForADrivePatternBake {
 [Serializable]public class TargetInput {public string field,path,exportId;public int index;}
 [Serializable]public class ElementInput {public string type,path,exportId;public TargetInput[] targets;}
 [Serializable]public class PatternInput {public int index;public string key,name,source,sourceBehaviorId,rewardPath,startPath,endPath;public ElementInput[] elements;}
 [Serializable]public class VehicleInput {public int index;public string key,name,source,sourceId;}
 [Serializable]public class Inputs {public PatternInput[] patterns;public VehicleInput[] vehicles;}
 [Serializable]public class Point {public string path,type,field;public int index;public Vector3 local;public Vector2 point;public Rect bounds;public bool active;}
 [Serializable]public class ColliderRow {public string path,type;public bool active,isTrigger;public Vector3 localCenter,size;public Rect bounds;}
 [Serializable]public class Picture {public string key,file,source,sourceSha256;public int width,height;public Vector2 pivot,holdPivot;public Rect alphaBounds;public float unitsPerPixel;public string gripEvidence;}
 [Serializable]public class Pattern {public int index;public string key,name,source,sourceSha256,sourceBehaviorId,obstaclesKey,rewardKey;public int width,height;public float sourceSpan;public Vector3 start,end;public Point reward;public Point[] elements;public ColliderRow[] colliders;}
 [Serializable]public class Report {public int format=1;public Picture[] pictures;public Pattern[] patterns;public string[] limits;}
 static string Output=>Path.GetFullPath(Environment.GetEnvironmentVariable("LITTLE_WEEPS_DRIVE_PATTERN_OUTPUT")??throw new Exception("Set fresh pattern output."));
 static readonly List<Picture> pictures=new List<Picture>();static readonly List<Pattern> patterns=new List<Pattern>();
 static string Hash(string p){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(p))).Replace("-","").ToLowerInvariant();}
 public static void Run(){try{
 if(Directory.Exists(Output))throw new Exception("Preserve existing output.");Directory.CreateDirectory(Output);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var input=JsonUtility.FromJson<Inputs>(File.ReadAllText("Assets/Research/PatternInputs.json"));
 foreach(var p in input.patterns)BakePattern(p);
 foreach(var v in input.vehicles)BakeSingle(v.source,v.key,null,null);
 const string stop="Assets/LDBMain/AddressableAssets/Embedded/Playpacks/GoForADrive/Prefabs/DriveTime/pfb_gfd_Road_PetrolStation_OneShot.prefab";
 BakeSingle(stop,"nozzle","Environment/Petrol_Handle","Group/Connectivity/Hole_Logical");BakeSingle(stop,"petrol-stop",null,null);
 File.WriteAllText(Path.Combine(Output,"pattern-content.json"),JsonUtility.ToJson(new Report{pictures=pictures.ToArray(),patterns=patterns.ToArray(),limits=new[]{"Static original prefab configuration and geometry only; original timing and reward code are not executed.","Each pattern contains its actual source reward; successful collection remains conditional on contact in production rules.","Orthographic asset bake preserves original geometry and relative positions; material lighting is approximated.","Traffic/ordinary prop holdPivot uses alpha center. Nozzle holdPivot projects exact original Hole_Logical grip."}},true));Debug.Log("DRIVE_PATTERNS_COMPLETE "+patterns.Count+" "+pictures.Count);EditorApplication.Exit(0);
 }catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}

 public static void RunFixtures(){try{
 if(Directory.Exists(Output))throw new Exception("Preserve existing fixture output.");Directory.CreateDirectory(Output);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);
 const string prefix="Assets/LDBMain/AddressableAssets/Embedded/Playpacks/GoForADrive/Prefabs/DriveTime/";
 BakeFixture(prefix+"pfb_gfd_Road_Toilet_OneShot.prefab","toilet",new[]{"Environment/Tree","Environment/Tree_1","Environment/Tree_2","Environment/dogsign"});
 BakeFixture(prefix+"pfb_gfd_Road_Roadworks_OneShot.prefab","rubble",new[]{"3D Elements_1/group/RoadworkGroup"});
 BakeFixture(prefix+"pfb_gfd_Road_PetrolStation_OneShot.prefab","petrol-stop",new[]{"Environment/Petrol_Station/Model"});
 File.WriteAllText(Path.Combine(Output,"fixture-content.json"),JsonUtility.ToJson(new Report{pictures=pictures.ToArray(),patterns=Array.Empty<Pattern>(),limits=new[]{"Fixture-only source render selection excludes scrolling scenery, floor meshes and unrelated shadows.","Toilet activity's original fixture is the tree cluster with dog sign; no cubicle was present.","Rubble is the exact interactive RoadworkGroup (bricks, spade and boulder); source traffic light is separately available in existing red/green keys.","Original source geometry and active renderer states preserved; no original game scripts execute."}},true));Debug.Log("DRIVE_FIXTURES_COMPLETE "+pictures.Count);EditorApplication.Exit(0);
 }catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 static void BakeFixture(string source,string key,string[] selected){var g=Create(source);var all=g.GetComponentsInChildren<Renderer>(true);var enabled=all.ToDictionary(r=>r,r=>r.enabled);foreach(var r in all)r.enabled=false;
 foreach(var path in selected){var t=Find(g.transform,path);foreach(var r in t.GetComponentsInChildren<Renderer>(true))r.enabled=enabled[r]&&r.gameObject.activeInHierarchy;}
 var c=CameraFor(g);var image=Capture(c);var crop=Alpha(image);Save(image,crop,key+"-fixture",source,c,g.transform);var row=pictures.Last();row.key=key;
 File.WriteAllText(Path.Combine(Output,key+"-selection.txt"),string.Join("\n",selected)+"\nRENDERERS\n"+string.Join("\n",all.Where(r=>r.enabled).Select(r=>AnimationUtility.CalculateTransformPath(r.transform,g.transform))));UnityEngine.Object.DestroyImmediate(image);UnityEngine.Object.DestroyImmediate(c.gameObject);UnityEngine.Object.DestroyImmediate(g);}
 static GameObject Create(string source){var g=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(source));g.transform.position=Vector3.zero;g.SetActive(true);foreach(var t in g.GetComponentsInChildren<Transform>(true))GameObjectUtility.RemoveMonoBehavioursWithMissingScript(t.gameObject);foreach(var r in g.GetComponentsInChildren<Renderer>(true))GoForADriveBake.Recover(r);return g;}
 static Camera CameraFor(GameObject g){var rr=g.GetComponentsInChildren<Renderer>().Where(r=>r.enabled&&!(r is ParticleSystemRenderer)).ToArray();if(rr.Length==0)throw new Exception("No geometry "+g.name);var b=rr[0].bounds;foreach(var r in rr)b.Encapsulate(r.bounds);var c=new GameObject("Source pattern camera").AddComponent<Camera>();c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=Color.clear;c.orthographic=true;c.aspect=2;c.orthographicSize=Mathf.Max(b.size.y*.5f,b.size.x*.25f)*1.2f;c.transform.position=b.center+new Vector3(0,.6f,-12);c.transform.LookAt(b.center);return c;}
 static Vector2 Pixel(Camera c,Vector3 p){var v=c.WorldToViewportPoint(p);return new Vector2(v.x*1024,(1-v.y)*512);}
 static Texture2D Capture(Camera c){var rt=new RenderTexture(1024,512,24,RenderTextureFormat.ARGB32);c.targetTexture=rt;c.Render();RenderTexture.active=rt;var image=new Texture2D(1024,512,TextureFormat.RGBA32,false);image.ReadPixels(new Rect(0,0,1024,512),0,0);image.Apply();c.targetTexture=null;RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(rt);return image;}
 static RectInt Alpha(Texture2D t){var p=t.GetPixels32();int l=t.width,r=0,b=t.height,u=0;for(int y=0;y<t.height;y++)for(int x=0;x<t.width;x++)if(p[y*t.width+x].a>0){l=Math.Min(l,x);r=Math.Max(r,x+1);b=Math.Min(b,y);u=Math.Max(u,y+1);}if(r<=l||u<=b)throw new Exception("Empty pixels");return new RectInt(l,b,r-l,u-b);}
 static Picture Save(Texture2D image,RectInt crop,string key,string source,Camera c,Transform pivot,Transform hold=null){var t=new Texture2D(crop.width,crop.height,TextureFormat.RGBA32,false);t.SetPixels(image.GetPixels(crop.x,crop.y,crop.width,crop.height));t.Apply();string file=key+".png";File.WriteAllBytes(Path.Combine(Output,file),t.EncodeToPNG());var a=Alpha(t);var v=Pixel(c,pivot.position);var hp=hold?Pixel(c,hold.position):new Vector2(crop.x+crop.width*.5f,512-crop.y-crop.height*.5f);var row=new Picture{key=key,file=file,source=source,sourceSha256=Hash(source),width=crop.width,height=crop.height,pivot=new Vector2(v.x-crop.x,512-v.y-crop.y),holdPivot=new Vector2(hp.x-crop.x,512-hp.y-crop.y),unitsPerPixel=c.orthographicSize*2/512,alphaBounds=new Rect(a.x/(float)t.width,1-(a.y+a.height)/(float)t.height,a.width/(float)t.width,a.height/(float)t.height),gripEvidence=hold?"Exact original Hole_Logical transform projected into this bake.":"Family alpha-center at hand adaptation."};pictures.Add(row);UnityEngine.Object.DestroyImmediate(t);return row;}
 static Rect Bounds(Camera c,Bounds b,RectInt crop){var lo=new Vector2(float.MaxValue,float.MaxValue);var hi=new Vector2(float.MinValue,float.MinValue);foreach(int x in new[]{-1,1})foreach(int y in new[]{-1,1})foreach(int z in new[]{-1,1}){var v=Pixel(c,b.center+Vector3.Scale(b.extents,new Vector3(x,y,z)));v=new Vector2((v.x-crop.x)/crop.width,(v.y-(512-crop.y-crop.height))/crop.height);lo=Vector2.Min(lo,v);hi=Vector2.Max(hi,v);}return new Rect(lo,hi-lo);}
 static Point Describe(Transform root,Transform t,Camera c,RectInt crop,string type,string field=null,int index=0){var v=Pixel(c,t.position);var rr=t.GetComponentsInChildren<Renderer>(true).Where(r=>!(r is ParticleSystemRenderer)).ToArray();Bounds b=rr.Length>0?rr[0].bounds:new Bounds(t.position,Vector3.zero);foreach(var r in rr)b.Encapsulate(r.bounds);return new Point{path=AnimationUtility.CalculateTransformPath(t,root),type=type,field=field,index=index,local=root.InverseTransformPoint(t.position),point=new Vector2((v.x-crop.x)/crop.width,(v.y-(512-crop.y-crop.height))/crop.height),bounds=Bounds(c,b,crop),active=t.gameObject.activeInHierarchy};}
 static Transform Find(Transform root,string path){var t=string.IsNullOrEmpty(path)?root:root.Find(path);if(!t)throw new Exception("Missing exact path "+path);return t;}
 static void BakePattern(PatternInput input){var g=Create(input.source);var c=CameraFor(g);var full=Capture(c);var crop=Alpha(full);var reward=Find(g.transform,input.rewardPath);var rp=Describe(g.transform,reward,c,crop,"WindowGamesStarReward");var elements=new List<Point>();foreach(var e in input.elements){elements.Add(Describe(g.transform,Find(g.transform,e.path),c,crop,e.type));foreach(var t in e.targets)elements.Add(Describe(g.transform,Find(g.transform,t.path),c,crop,e.type,t.field,t.index));}
 var colliders=g.GetComponentsInChildren<Collider>(true).Select(t=>new ColliderRow{path=AnimationUtility.CalculateTransformPath(t.transform,g.transform),type=t.GetType().Name,active=t.enabled&&t.gameObject.activeInHierarchy,isTrigger=t.isTrigger,localCenter=g.transform.InverseTransformPoint(t.bounds.center),size=t.bounds.size,bounds=Bounds(c,t.bounds,crop)}).ToArray();
 Save(full,crop,input.key,input.source,c,g.transform);reward.gameObject.SetActive(false);var obstacles=Capture(c);Save(obstacles,crop,input.key+"-obstacles",input.source,c,g.transform);reward.gameObject.SetActive(true);foreach(var r in g.GetComponentsInChildren<Renderer>(true))r.enabled=false;foreach(var r in reward.GetComponentsInChildren<Renderer>(true))r.enabled=true;var star=Capture(c);Save(star,crop,input.key+"-reward",input.source,c,g.transform);
 var start=Find(g.transform,input.startPath).localPosition;var end=Find(g.transform,input.endPath).localPosition;patterns.Add(new Pattern{index=input.index,key=input.key,name=input.name,source=input.source,sourceSha256=Hash(input.source),sourceBehaviorId=input.sourceBehaviorId,width=crop.width,height=crop.height,start=start,end=end,sourceSpan=Math.Abs(end.x-start.x),reward=rp,elements=elements.ToArray(),colliders=colliders,obstaclesKey=input.key+"-obstacles",rewardKey=input.key+"-reward"});foreach(var t in new[]{full,obstacles,star})UnityEngine.Object.DestroyImmediate(t);UnityEngine.Object.DestroyImmediate(c.gameObject);UnityEngine.Object.DestroyImmediate(g);}
 static void BakeSingle(string source,string key,string subpath,string grip){var whole=Create(source);var target=whole.transform;if(subpath!=null){target=Find(whole.transform,subpath);target.SetParent(null,true);target.position=Vector3.zero;whole.SetActive(false);}var c=CameraFor(target.gameObject);var image=Capture(c);var crop=Alpha(image);Save(image,crop,key,source,c,target,grip!=null?Find(target,grip):null);UnityEngine.Object.DestroyImmediate(image);UnityEngine.Object.DestroyImmediate(c.gameObject);if(target!=whole.transform)UnityEngine.Object.DestroyImmediate(target.gameObject);UnityEngine.Object.DestroyImmediate(whole);}
}
